INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (980431, 'Avatar Aang: The Last Airbender', 'Avatar Aang, the world''s last Airbender, learns of an ancient power that could save his culture from extinction. With the help of his friends, he embarks on a global quest to find it before it falls into the wrong hands and threatens to upend the peace they sacrificed everything to achieve.', '2026-07-24', 9.267, 'https://image.tmdb.org/t/p/w500/3sgnSfNT27Bx5O5ukr7B26mhEQq.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
