INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (1727780, 'Borderline', 'Convinced they are our secret saviors, rogue U.S. operatives abduct Mexican gang members and seed them across major American cities, unleashing criminal chaos, swaying voters by playing on nativist prejudices, and forcing law enforcement into a race to expose the plot as the escalating carnage threatens democracy itself.', '2026-07-17', 5.885, 'https://image.tmdb.org/t/p/w500/sAA2mjpYJFAKydtzG4P4aHC4mZk.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
