INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (1510795, 'Shake, Rattle & Roll: Evil Origins', 'In 1775 during the Spanish colonial period in the Philippines, nuns attempts to survive the night after an unknown evil was set free in their cloister. Meanwhile in 2025, a group of friends attend a Halloween masquerade ball which was attacked by a serial killer. Fast forward to the future in 2050, a post-apocalytic Philippines is ruled by the aswang.', '2026-06-05', 4.0, 'https://image.tmdb.org/t/p/w500/2ayOQIh18qhJRoajoAxxGuZXry2.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
